"<PROGRAM_FILES>\\POWERS~1\\7\\pwsh.exe" -Command '$auditCompute = @'"'
const fs = require('node:fs');
const assert = require('node:assert/strict');
const read = file => {
  const [header, ...lines] = fs.readFileSync(file, 'utf8').trimEnd().split(/\\r?\\n/);
  const fields = header.split(',');
  return lines.map(line => Object.fromEntries(line.split(',').map((value, i) => [fields[i], value])));
};
const pairs = read('evidence/pairs.csv');
const reference = new Map(read('evidence/reference.csv').map(row => [row.pair_id, row]));
const guide = new Map(read('evidence/guide.csv').map(row => [row.pair_id, row]));
const positiveTime = value => value "'!== '"'' && Number.isFinite(Number(value)) && Number(value) > 0;
const rows = pairs.map(pair => {
  const ref = reference.get(pair.pair_id);
  const next = guide.get(pair.pair_id);
  assert.ok(ref && next);
  const eligible = positiveTime(ref.seconds) && positiveTime(next.seconds);
  return {...pair, reference_seconds: positiveTime(ref.seconds) ? Number(ref.seconds) : null, guide_seconds: positiveTime(next.seconds) ? Number(next.seconds) : null, eligible, time_saved_seconds: eligible ? Number(ref.seconds) - Number(next.seconds) : null, reference_correct: ref.correct === 'true', guide_correct: next.correct === 'true', reference_assisted: ref.assisted === 'true', guide_assisted: next.assisted === 'true'};
});
const timed = rows.filter(row => row.eligible);
const sum = (list, key) => list.reduce((total, row) => total + row[key], 0);
const metrics = {
  eligible_time_pairs: timed.length,
  reference_seconds: sum(timed, 'reference_seconds'),
  guide_seconds: sum(timed, 'guide_seconds'),
  time_saved_seconds: sum(timed, 'time_saved_seconds'),
  faster_pairs: timed.filter(row => row.time_saved_seconds > 0).length,
  slower_pairs: timed.filter(row => row.time_saved_seconds < 0).length,
  tied_pairs: timed.filter(row => row.time_saved_seconds === 0).length,
  accuracy_pairs: rows.length,
  reference_correct: rows.filter(row => row.reference_correct).length,
  guide_correct: rows.filter(row => row.guide_correct).length
};
assert.equal(metrics.reference_seconds - metrics.guide_seconds, metrics.time_saved_seconds);
assert.equal(metrics.faster_pairs + metrics.slower_pairs + metrics.tied_pairs, metrics.eligible_time_pairs);
const orderGroups = ['reference', 'guide'].map(first => {
  const group = timed.filter(row => row.first_format === first);
  return {first_format: first, eligible_pairs: group.map(row => row.pair_id), reference_seconds: sum(group, 'reference_seconds'), guide_seconds: sum(group, 'guide_seconds'), time_saved_seconds: sum(group, 'time_saved_seconds')};
});
const volunteers = [...new Set(rows.map(row => row.volunteer_id))].map(id => ({volunteer_id: id, rows: rows.filter(row => row.volunteer_id === id)}));
for (const volunteer of volunteers) {
  assert.equal(volunteer.rows.length, 2);
  assert.deepEqual(volunteer.rows.map(row => row.first_format).sort(), ['guide', 'reference']);
}
process.stdout.write(JSON.stringify({metrics, percentage_saved: 100 * metrics.time_saved_seconds / metrics.reference_seconds, rows, orderGroups, assistance: {reference: rows.filter(row => row.reference_assisted).map(row => row.pair_id), guide: rows.filter(row => row.guide_assisted).map(row => row.pair_id)}, accuracyTransitions: {both_correct: rows.filter(row => row.reference_correct && row.guide_correct).length, reference_only_correct: rows.filter(row => row.reference_correct && "'!row.guide_correct).length, guide_only_correct: rows.filter(row => !row.reference_correct && row.guide_correct).length, both_incorrect: rows.filter(row => !row.reference_correct && !row.guide_correct).length}}, null, 2) + '"'\\n');
