"<PROGRAM_FILES>\\POWERS~1\\7\\pwsh.exe" -Command '$ErrorActionPreference = '"'Stop'
"'$pairRecords = @(Import-Csv -LiteralPath '"'evidence/pairs.csv')
"'$referenceRecords = @(Import-Csv -LiteralPath '"'evidence/reference.csv')
"'$guideRecords = @(Import-Csv -LiteralPath '"'evidence/guide.csv')
"'$referenceById = @{}
$guideById = @{}
foreach ($record in $referenceRecords) { $referenceById.Add($record.pair_id, $record) }
foreach ($record in $guideRecords) { $guideById.Add($record.pair_id, $record) }
$joinedRecords = @(foreach ($pair in $pairRecords) {
  if (!$referenceById.ContainsKey($pair.pair_id) -or !$guideById.ContainsKey($pair.pair_id)) { throw "Unmatched ID: $($pair.pair_id)" }
  $referenceRecord = $referenceById[$pair.pair_id]
  $guideRecord = $guideById[$pair.pair_id]
  $eligible = ![string]::IsNullOrWhiteSpace($referenceRecord.seconds) -and ![string]::IsNullOrWhiteSpace($guideRecord.seconds) -and [double]$referenceRecord.seconds -gt 0 -and [double]$guideRecord.seconds -gt 0
  if ($eligible) {
    [PSCustomObject]@{ pair_id = $pair.pair_id; reference_seconds = [int]$referenceRecord.seconds; guide_seconds = [int]$guideRecord.seconds; saved = [int]$referenceRecord.seconds - [int]$guideRecord.seconds }
  }
})
$expectedMetrics = [ordered]@{
  eligible_time_pairs = $joinedRecords.Count
  reference_seconds = ($joinedRecords | Measure-Object -Property reference_seconds -Sum).Sum
  guide_seconds = ($joinedRecords | Measure-Object -Property guide_seconds -Sum).Sum
  time_saved_seconds = ($joinedRecords | Measure-Object -Property saved -Sum).Sum
  faster_pairs = @($joinedRecords | Where-Object { $_.saved -gt 0 }).Count
  slower_pairs = @($joinedRecords | Where-Object { $_.saved -lt 0 }).Count
  tied_pairs = @($joinedRecords | Where-Object { $_.saved -eq 0 }).Count
  accuracy_pairs = $pairRecords.Count
  reference_correct = @($referenceRecords | Where-Object { $_.correct -ceq '"'true' }).Count
  guide_correct = @("'$guideRecords | Where-Object { $_.correct -ceq '"'true' }).Count
}
"'$actualMetrics = Get-Content -LiteralPath '"'audit/metrics.json' -Raw | ConvertFrom-Json
"'$actualNames = @($actualMetrics.PSObject.Properties.Name)
if (@(Compare-Object -ReferenceObject @($expectedMetrics.Keys) -DifferenceObject $actualNames).Count -ne 0) { throw '"'Metrics fields differ from protocol' }
foreach ("'$key in $expectedMetrics.Keys) {
  $actualValue = $actualMetrics.$key
  if ($actualValue.GetType().Name -notin @('"'Int32','Int64','Double','Decimal') -or "'$actualValue -ne $expectedMetrics[$key]) { throw "Metric mismatch or wrong type: $key" }
}
if ($actualMetrics.reference_seconds - $actualMetrics.guide_seconds -ne $actualMetrics.time_saved_seconds) { throw '"'Seconds identity failed' }
if ("'$actualMetrics.faster_pairs + $actualMetrics.slower_pairs + $actualMetrics.tied_pairs -ne $actualMetrics.eligible_time_pairs) { throw '"'Pair count identity failed' }
if (("'$joinedRecords.pair_id -join '"',') -cne 'P1,P2,P3,P4,P5,P6,P8') { throw 'Unexpected timing inclusion' }
if (@("'$referenceRecords | Where-Object { $_.correct -ceq '"'false' }).pair_id -cne 'P3') { throw 'Unexpected reference error' }
if (@("'$guideRecords | Where-Object { $_.correct -ceq '"'false' }).pair_id -cne 'P5') { throw 'Unexpected guide error' }
[PSCustomObject]@{ validation = 'PASS'; numeric_fields_checked = "'$actualNames.Count; eligible_ids = $joinedRecords.pair_id; percentage_saved = 100 * $actualMetrics.time_saved_seconds / $actualMetrics.reference_seconds; metrics = $actualMetrics } | ConvertTo-Json -Depth 4'
